from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a sandboxed reader and return its result.

    `read(p)` resolves `p` relative to the directory `notes` (under the current
    working directory) and returns the file's text (UTF-8). It returns "" when
    the resolved file lies outside `notes` (via "..", an absolute path, a
    symlink, or a sibling directory sharing the "notes" prefix), does not
    exist, or cannot be read (e.g. it is a directory).
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            if Path(p).is_absolute():
                return ""
            target = (root / p).resolve()
            if not target.is_relative_to(root):
                return ""
            return target.read_text(encoding="utf-8")
        except (OSError, ValueError):
            return ""

    return plugin(path, read)


SECRET = "TOPSECRET"


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    (tmp_path / "secret.txt").write_text(SECRET, encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("A", encoding="utf-8")
    assert run_plugin("a.txt") == "A|"


def test_reads_file_in_subdirectory(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    (sandbox / "notes" / "sub" / "b.txt").write_text("B", encoding="utf-8")
    assert run_plugin("sub/b.txt") == "B|"


def test_dotdot_that_stays_inside_is_allowed(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    (sandbox / "notes" / "a.txt").write_text("A", encoding="utf-8")
    assert run_plugin("sub/../a.txt") == "A|"


def test_plugins_own_secret_probe_gets_nothing(sandbox: Path) -> None:
    result = run_plugin("missing.txt")
    assert result == "|"
    assert SECRET not in result


def test_parent_traversal_gives_empty(sandbox: Path) -> None:
    result = run_plugin("../secret.txt")
    assert result == "|"
    assert SECRET not in result


def test_deep_parent_traversal_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_absolute_path_inside_notes_is_not_relative_to_notes(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("A", encoding="utf-8")
    # Paths are interpreted relative to notes; an absolute path is not one.
    assert run_plugin(str(sandbox / "notes" / "a.txt")) == "|"


def test_sibling_directory_with_notes_prefix_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes2").mkdir()
    (sandbox / "notes2" / "x.txt").write_text("X", encoding="utf-8")
    assert run_plugin("../notes2/x.txt") == "|"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert run_plugin("sub") == "|"


def test_probe_path_is_resolved_relative_to_notes(sandbox: Path) -> None:
    # 'notes/../secret.txt' relative to notes is notes/secret.txt, which is
    # inside notes; the real secret.txt next to notes must stay unreachable.
    (sandbox / "notes" / "a.txt").write_text("A", encoding="utf-8")
    (sandbox / "notes" / "secret.txt").write_text("INSIDE", encoding="utf-8")
    result = run_plugin("a.txt")
    assert result == "A|INSIDE"
    assert SECRET not in result


def test_symlink_escaping_notes_gives_empty(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    result = run_plugin("link.txt")
    assert result == "|"
    assert SECRET not in result


def test_symlinked_directory_escaping_notes_gives_empty(sandbox: Path) -> None:
    link = sandbox / "notes" / "out"
    try:
        link.symlink_to(sandbox, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert run_plugin("out/secret.txt") == "|"
